let raw = String($json.choices[0].message.content || '').trim();
// Strip markdown fences some models wrap JSON in.
raw = raw.replace(/^```[a-z]*\n?/i, '').replace(/\n?```\s*$/, '');
let grade;
let repaired = false;
try { grade = JSON.parse(raw); }
catch (e) {
  // Small models sometimes truncate the JSON mid-output — try repairing by
  // appending closing delimiters before giving up.
  repaired = true;
  grade = null;
  for (const closer of ['}', ']', '}', ']', '"'] ) {
    try { grade = JSON.parse(raw + closer); if (grade) break; } catch (_) {}
  }
  if (!grade) grade = { overall_score: 0, verdict: 'fail', parse_error: raw.slice(0, 500) };
}
// If the repaired JSON is missing core fields, keep the raw output so the
// failure is visible in Grist instead of silently grading 0.
const _required = ['overall_score', 'verdict', 'dimensions', 'strengths', 'improvements'];
if (repaired && _required.some(k => !(k in grade))) {
  grade.parse_error = 'incomplete JSON (repaired): ' + raw.slice(0, 600);
}
return [{
  json: {
    run_id: body.run_id,
    student_name: body.student_name,
    phone: body.phone,
    track: body.track || 'it',
    overall_score: grade.overall_score,
    verdict: grade.verdict,
    dimensions: grade.dimensions,
    strengths: grade.strengths,
    improvements: grade.improvements,
    transcript: ft.data || ft.transcript || (typeof ft === 'string' ? ft : JSON.stringify(ft)),
    parse_error: grade.parse_error || ''
  }
}];
